	'kaf34c103' => 'Schnitt 01',
	'kafabe9bb' => 'DER TAG',
	'kb016cee2' => 'Geschuppt, ausgenommen und von den Flossen befreit, bereit zum Braten auf Kräutern oder zum Backen in der Salzkruste.',
